import { useState } from 'react';
import { JxButton, JxInput } from '@jinx-ui/react';

interface RegistrationData {
  fullName: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
}

interface RegistrationStepperProps {
  onSubmit: (data: RegistrationData) => void;
}

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const INITIAL_DATA: RegistrationData = {
  fullName: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

export default function RegistrationStepper({ onSubmit }: RegistrationStepperProps) {
  const [stepIndex, setStepIndex] = useState(0);
  const [data, setData] = useState<RegistrationData>(INITIAL_DATA);

  const isLastStep = stepIndex === STEPS.length - 1;

  const setField = (field: keyof RegistrationData) => (value: string) => {
    setData((prev) => ({ ...prev, [field]: value }));
  };

  const goBack = () => setStepIndex((i) => Math.max(0, i - 1));
  const goNext = () => setStepIndex((i) => Math.min(STEPS.length - 1, i + 1));

  const handlePrimaryAction = () => {
    if (isLastStep) {
      onSubmit(data);
    } else {
      goNext();
    }
  };

  return (
    <div
      style={{
        maxWidth: 480,
        margin: '0 auto',
        padding: 'var(--jx-space-6)',
        borderRadius: 'var(--jx-radius-lg)',
        backgroundColor: 'var(--jx-color-surface)',
        border: '1px solid var(--jx-color-border)',
      }}
    >
      <ol
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          listStyle: 'none',
          margin: 0,
          padding: 0,
          marginBottom: 'var(--jx-space-6)',
        }}
      >
        {STEPS.map((label, index) => {
          const isActive = index === stepIndex;
          const isDone = index < stepIndex;
          return (
            <li
              key={label}
              style={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                gap: 'var(--jx-space-2)',
                flex: 1,
                textAlign: 'center',
              }}
            >
              <span
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  width: 28,
                  height: 28,
                  borderRadius: 'var(--jx-radius-full)',
                  fontSize: 'var(--jx-font-size-sm)',
                  fontWeight: 'var(--jx-font-weight-medium)',
                  color: isActive || isDone ? 'var(--jx-color-primary-contrast)' : 'var(--jx-color-text-muted)',
                  backgroundColor: isActive || isDone ? 'var(--jx-color-primary)' : 'var(--jx-color-surface-muted)',
                  border: '1px solid var(--jx-color-border)',
                }}
              >
                {index + 1}
              </span>
              <span
                style={{
                  fontSize: 'var(--jx-font-size-sm)',
                  color: isActive ? 'var(--jx-color-text)' : 'var(--jx-color-text-muted)',
                  fontWeight: isActive ? 'var(--jx-font-weight-medium)' : 'var(--jx-font-weight-regular)',
                }}
              >
                {label}
              </span>
            </li>
          );
        })}
      </ol>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)', minHeight: 220 }}>
        {stepIndex === 0 && (
          <>
            <JxInput
              label="Полное имя"
              value={data.fullName}
              onValueChange={setField('fullName')}
              placeholder="Иван Иванов"
            />
            <JxInput
              label="Email"
              type="email"
              value={data.email}
              onValueChange={setField('email')}
              placeholder="you@example.com"
            />
            <JxInput
              label="Телефон"
              type="tel"
              value={data.phone}
              onValueChange={setField('phone')}
              placeholder="+7 900 000-00-00"
            />
          </>
        )}

        {stepIndex === 1 && (
          <>
            <JxInput
              label="Страна"
              value={data.country}
              onValueChange={setField('country')}
              placeholder="Россия"
            />
            <JxInput
              label="Город"
              value={data.city}
              onValueChange={setField('city')}
              placeholder="Москва"
            />
            <JxInput
              label="Улица и дом"
              value={data.street}
              onValueChange={setField('street')}
              placeholder="ул. Ленина, д. 1"
            />
            <JxInput
              label="Почтовый индекс"
              value={data.zip}
              onValueChange={setField('zip')}
              placeholder="101000"
            />
          </>
        )}

        {stepIndex === 2 && (
          <dl
            style={{
              display: 'grid',
              gridTemplateColumns: '1fr 1fr',
              rowGap: 'var(--jx-space-3)',
              columnGap: 'var(--jx-space-2)',
              margin: 0,
            }}
          >
            <dt style={{ color: 'var(--jx-color-text-muted)' }}>Имя</dt>
            <dd style={{ margin: 0 }}>{data.fullName || '—'}</dd>

            <dt style={{ color: 'var(--jx-color-text-muted)' }}>Email</dt>
            <dd style={{ margin: 0 }}>{data.email || '—'}</dd>

            <dt style={{ color: 'var(--jx-color-text-muted)' }}>Телефон</dt>
            <dd style={{ margin: 0 }}>{data.phone || '—'}</dd>

            <dt style={{ color: 'var(--jx-color-text-muted)' }}>Страна</dt>
            <dd style={{ margin: 0 }}>{data.country || '—'}</dd>

