            <dd style={{ margin: 0 }}>{data.city || '—'}</dd>

            <dt style={{ color: 'var(--jx-color-text-muted)' }}>Адрес</dt>
            <dd style={{ margin: 0 }}>{data.street || '—'}</dd>

            <dt style={{ color: 'var(--jx-color-text-muted)' }}>Индекс</dt>
            <dd style={{ margin: 0 }}>{data.zip || '—'}</dd>
          </dl>
        )}
      </div>

      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          marginTop: 'var(--jx-space-6)',
          gap: 'var(--jx-space-3)',
        }}
      >
        <JxButton variant="secondary" onClick={goBack} disabled={stepIndex === 0}>
          Назад
        </JxButton>
        <JxButton variant="primary" onClick={handlePrimaryAction}>
          {isLastStep ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </div>
  );
}

